fn is_greater(n: i32, a: Vec<i32>) -> bool {
    // Requires: n is a 32-bit integer and a is a vector of 32-bit integers
    // Ensures: Returns true if n is greater than all elements in a, or if a is empty
    // Invariant: At any point in the loop, if the loop has not returned false, 
    //            then n is greater than all elements checked so far.
    // Decreases: The length of the vector a, ensuring that the loop will terminate.

    // An empty array means there are no elements to compare, so return true
    if a.is_empty() {
        return true;
    }
    
    // Check if n is greater than all elements in the array
    let mut i = 0; // Loop index
    let len = a.len(); // Length of the vector

    // Loop invariant: 0 <= i <= len && (forall j: 0 <= j < i => n > a[j])
    while i < len {
        // Assert that the loop invariant holds
        assert!(0 <= i && i <= len);
        for j in 0..i {
            assert!(n > a[j]);
        }

        // Check the current value
        if n <= a[i] {
            return false; // Found an element that is greater than or equal to n
        }
        
        i += 1; // Increment the index
    }
    
    true // n is greater than all elements in the array
}